import React, { useEffect } from "react";

const tailwindConfig = `
  tailwind.config = {
    darkMode: "class",
    theme: {
      extend: {
        "colors": {
          "inverse-on-surface": "#2d2f44",
          "on-surface-variant": "#e7bdbb",
          "on-secondary-fixed-variant": "#3c475a",
          "outline": "#ad8886",
          "on-surface": "#e0e0fc",
          "on-tertiary-container": "#5c000b",
          "on-secondary-fixed": "#101c2c",
          "secondary-fixed-dim": "#bbc7dd",
          "on-tertiary-fixed": "#410005",
          "inverse-primary": "#bf0027",
          "error-container": "#93000a",
          "surface-container-highest": "#313349",
          "on-primary": "#680011",
          "surface-bright": "#36384d",
          "primary-container": "#ff535a",
          "primary-fixed": "#ffdad8",
          "surface-container-lowest": "#0a0c20",
          "secondary-container": "#3c475a",
          "secondary": "#bbc7dd",
          "on-tertiary": "#68000e",
          "secondary-fixed": "#d7e3fa",
          "on-background": "#e0e0fc",
          "error": "#ffb4ab",
          "on-secondary": "#253142",
          "surface-container-high": "#26283d",
          "surface-dim": "#101225",
          "tertiary-fixed-dim": "#ffb3af",
